<?php
require_once __DIR__.'/includes/auth.php';$u=require_role('customer');$cats=db()->query("SELECT id,name FROM categories WHERE is_active=1 ORDER BY name")->fetchAll();$services=db()->query("SELECT id,category_id,name FROM services WHERE is_active=1 ORDER BY name")->fetchAll();$err=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$cat=(int)($_POST['category_id']??0);$sid=(int)($_POST['service_id']??0);$title=trim((string)($_POST['title']??''));$desc=trim((string)($_POST['description']??''));$loc=trim((string)($_POST['location_text']??''));try{$date=nullable_date($_POST['preferred_date']??null,false,'Preferred date');$time=nullable_time($_POST['preferred_time']??null,'Preferred time');$bmin=nullable_money($_POST['budget_min']??null,'Minimum budget');$bmax=nullable_money($_POST['budget_max']??null,'Maximum budget');}catch(RuntimeException $e){$err[]=$e->getMessage();$date=$time=$bmin=$bmax=null;}if(!$cat)$err[]='Please select a service category.';if(!$sid)$err[]='Please select a service.';if(!$title)$err[]='Please enter what you need.';elseif(text_length($title)>180)$err[]='Requirement title is too long.';if(!$desc)$err[]='Please describe your requirement.';elseif(text_length($desc)>10000)$err[]='Requirement description is too long.';if(!$loc)$err[]='Please enter the service location.';elseif(text_length($loc)>255)$err[]='Service location is too long.';$valid=false;foreach($services as $x)if($x['id']==$sid&&$x['category_id']==$cat)$valid=true;if(!$valid)$err[]='Please select a valid service for this category.';if($bmin!==null&&$bmax!==null&&$bmin>$bmax)$err[]='Minimum budget cannot exceed maximum budget.';
if(!$err){$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare("INSERT INTO service_requests(customer_id,category_id,service_id,request_type,title,description,location_text,preferred_date,preferred_time,budget_min,budget_max,status) VALUES(?,?,?,'requirement',?,?,?,?,?,?,?,'pending')");$q->execute([$u['id'],$cat,$sid,$title,$desc,$loc,$date,$time,$bmin,$bmax]);$id=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO request_status_history(request_id,status,changed_by,note) VALUES(?,'pending',?,'Requirement posted')")->execute([$id,$u['id']]);$pdo->commit();flash('success','Requirement posted successfully. Matching providers can now find it.');redirect('customer/requests.php');}catch(Throwable $e){$pdo->rollBack();$err[]='Could not post your requirement. Please try again.';}}}
$pageTitle='Post a Requirement — LocalConnect';require __DIR__.'/includes/header.php';?>
<div class="container py-5" style="max-width:900px"><div class="soft-card p-4 p-md-5"><span class="badge bg-primary-subtle text-primary mb-2">Open marketplace request</span><h1 class="fw-bold">Post a Requirement</h1><p class="text-muted">Describe the work you need. Providers offering the selected service can view it in Available Requirements.</p><?php foreach($err as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?><form method="post" class="row g-3"><?=csrf_field()?><div class="col-md-6"><label class="form-label">Category *</label><select id="category" name="category_id" class="form-select" data-service-filter="#service" required><option value="">Select</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Service *</label><select id="service" name="service_id" class="form-select" required><option value="">Select</option><?php foreach($services as $s):?><option data-category="<?=$s['category_id']?>" value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">What do you need? *</label><input name="title" maxlength="180" class="form-control" placeholder="e.g. Switchboard repair" required></div><div class="col-12"><label class="form-label">Description *</label><textarea name="description" rows="4" class="form-control" placeholder="Explain the problem or work required" required></textarea></div><div class="col-12"><label class="form-label">Location *</label><input name="location_text" class="form-control" required value="<?=e(trim(($u['area']??'').', '.($u['city']??''),', '))?>"></div><div class="col-md-6"><label class="form-label">Preferred date</label><input type="date" min="<?=date('Y-m-d')?>" name="preferred_date" class="form-control"></div><div class="col-md-6"><label class="form-label">Preferred time</label><input type="time" name="preferred_time" class="form-control"></div><div class="col-md-6"><label class="form-label">Budget min (₹)</label><input type="number" min="0" name="budget_min" class="form-control"></div><div class="col-md-6"><label class="form-label">Budget max (₹)</label><input type="number" min="0" name="budget_max" class="form-control"></div><div class="col-12"><button class="btn btn-primary btn-lg">Post Requirement</button></div></form></div></div><?php require __DIR__.'/includes/footer.php';?>